import{_ as e,c as t,o as s,a4 as o}from"./chunks/framework.ttppV29E.js";const n="/assets/mcp-permission-gated-endpoint.-BpIr7I6.png",a="/assets/mcp-permission-tools-compare.BwpSUUOl.png",w=JSON.parse('{"title":"MCP Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"docs/mcp-servers/permissions.md","filePath":"docs/mcp-servers/permissions.md","lastUpdated":1791474926000}'),i={name:"docs/mcp-servers/permissions.md"},r=o('<h1 id="mcp-permissions" tabindex="-1">MCP Permissions <a class="header-anchor" href="#mcp-permissions" aria-label="Permalink to &quot;MCP Permissions&quot;">​</a></h1><p>AireGlu MCP servers can show each user only the tools and resources they are allowed to use, and run them as that user. This page explains the layers of access control for MCP, and how they fit together.</p><h2 id="layers-of-access" tabindex="-1">Layers of access <a class="header-anchor" href="#layers-of-access" aria-label="Permalink to &quot;Layers of access&quot;">​</a></h2><table><thead><tr><th>Layer</th><th>Question</th><th>Configured on</th><th>Result when denied</th></tr></thead><tbody><tr><td><strong>Connect</strong></td><td>Can this person use AireGlu MCP at all?</td><td>The user&#39;s <code>run:Mcp</code> permission in AireIdentity</td><td>Every MCP request is rejected (401)</td></tr><tr><td><strong>Tool / resource</strong></td><td>Which tools and resources can they see and use?</td><td><a href="/docs/endpoint-authentication/permission-gating.html">Permission gating</a> on each target endpoint</td><td>Tool hidden from the list, and refused if called</td></tr><tr><td><strong>Downstream</strong></td><td>What can AireGlu do on their behalf?</td><td>A <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection on the endpoint&#39;s tasks</td><td>Downstream call fails</td></tr><tr><td><strong>Data</strong></td><td>Which records can they see?</td><td>The downstream API</td><td>Downstream API returns an error or filtered data</td></tr></tbody></table><p>Each layer answers one question with one source of truth, so you never have to reconcile two systems deciding the same thing.</p><h2 id="connecting-to-an-mcp-server" tabindex="-1">Connecting to an MCP server <a class="header-anchor" href="#connecting-to-an-mcp-server" aria-label="Permalink to &quot;Connecting to an MCP server&quot;">​</a></h2><p>To connect a client, the user needs the <code>run:Mcp</code> permission on the <code>AireGluMcp</code> scope, and MCP must be enabled for the tenant. See <a href="/docs/mcp-servers/#permissions">Permissions</a> and <a href="/docs/mcp-servers/connecting-clients.html#authentication">Connecting Clients</a>.</p><p>A user who signs in without <code>run:Mcp</code> can&#39;t use any tools on any server.</p><h2 id="permission-aware-tools-and-resources" tabindex="-1">Permission-aware tools and resources <a class="header-anchor" href="#permission-aware-tools-and-resources" aria-label="Permalink to &quot;Permission-aware tools and resources&quot;">​</a></h2><p>Tool-level access isn&#39;t configured on the MCP server. It is configured on the <strong>target endpoint</strong>, using <a href="/docs/endpoint-authentication/permission-gating.html">Permission Gating</a> on its Open ID Connect Bearer Token authentication. Because it lives on the endpoint, the same rule applies whether the endpoint is called as an MCP tool or directly over HTTP.</p><h3 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h3><ol><li>Open the endpoint the tool or resource targets.</li><li>Under <strong>Authentication</strong>, add <strong>Open ID Connect Bearer Token</strong>: <ul><li><strong>Authority</strong>: your AireIdentity instance</li><li><strong>Audiences</strong>: <code>AireGluMcp</code></li></ul></li><li>Tick <strong>Fetch and validate permissions for Target Scope(s)</strong> and add the Target Scope(s) and permissions a user needs to use this tool. See <a href="/docs/endpoint-authentication/permission-gating.html#configuring-permission-gating">Configuring permission gating</a>.</li><li>Save the endpoint. No change is needed on the MCP server.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>AireGluMcp</code> is the only audience you need. Some MCP clients (Claude.ai, Claude Desktop, <code>mcp-remote</code>) receive tokens whose audience is the server&#39;s own URL, <code>https://&lt;runtime-host&gt;/mcp/&lt;tenancy&gt;/&lt;server-name&gt;</code>. AireGlu accepts this automatically on MCP calls.</p></div><p><img src="'+n+'" alt="Target endpoint with permission gating for MCP" width="473"></p><h3 id="what-users-see" tabindex="-1">What users see <a class="header-anchor" href="#what-users-see" aria-label="Permalink to &quot;What users see&quot;">​</a></h3><p>When a client lists tools or resources, AireGlu checks each gated endpoint against the signed-in user&#39;s permissions:</p><ul><li><strong>Allowed</strong>: the tool or resource is listed and can be used.</li><li><strong>Not allowed</strong>: the tool or resource is <strong>left out of the list</strong>. The AI assistant never sees it, so it can&#39;t try to use it.</li></ul><p>Permissions are checked again when a tool is called or a resource is read. If the user&#39;s access was removed since the list was fetched, the call returns an error result:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Permission denied: you do not have the required permission for this operation.</span></span></code></pre></div><p>Endpoints without permission gating are visible to every user who can connect.</p><p><img src="'+a+'" alt="The same MCP server listed in Claude Code&#39;s /mcp view for two users: one sees public-widget and gated-widget, the other only public-widget"></p><p><em>Illustration: the same server viewed with <code>/mcp</code> in Claude Code by a user with the required permissions (left) and one without (right).</em></p><h3 id="why-tools-are-hidden-rather-than-refused" tabindex="-1">Why tools are hidden rather than refused <a class="header-anchor" href="#why-tools-are-hidden-rather-than-refused" aria-label="Permalink to &quot;Why tools are hidden rather than refused&quot;">​</a></h3><ul><li><strong>The assistant only plans with tools it can use.</strong> If a tool appears and then fails, the assistant tends to retry, guess at the cause or work around it. Hiding it avoids that.</li><li><strong>No information leaks.</strong> Users can&#39;t see the names or descriptions of tools they aren&#39;t allowed to use.</li><li><strong>Access changes take effect immediately.</strong> Lookups aren&#39;t cached, so granting or revoking a role in AireIdentity changes the tool list the next time the client refreshes it.</li></ul><h3 id="things-to-know" tabindex="-1">Things to know <a class="header-anchor" href="#things-to-know" aria-label="Permalink to &quot;Things to know&quot;">​</a></h3><ul><li>On MCP calls, only the gated Open ID Connect Bearer Token method is checked. Other authentication methods on the endpoint (for example API Key or IP Address) apply to direct HTTP calls, not to MCP.</li><li>Each gated tool makes a live permission lookup when tools are listed. Gate the tools that need it, not every tool by default.</li><li>If the permission lookup fails, the tool is hidden (fail closed).</li></ul><h2 id="calling-downstream-apis-as-the-user" tabindex="-1">Calling downstream APIs as the user <a class="header-anchor" href="#calling-downstream-apis-as-the-user" aria-label="Permalink to &quot;Calling downstream APIs as the user&quot;">​</a></h2><p>When a tool calls another system, it can use the MCP user&#39;s identity instead of a shared service account. The user&#39;s MCP token is available to the endpoint&#39;s tasks as <code>request.userToken</code>. Exchange it with a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection rather than forwarding it:</p><table><thead><tr><th>Task parameter</th><th>Value</th></tr></thead><tbody><tr><td><code>subject_token</code></td><td><span><code>{{ request.userToken }}</code></span></td></tr><tr><td><code>scope</code></td><td><span><code>{{ authentication.targetScopes[0] }}</code></span> (or leave blank to use the connection&#39;s Target Scope)</td></tr></tbody></table><p>The downstream API then receives a token for the same user, scoped only to that API, and can apply its own record-level rules.</p><div class="warning custom-block"><p class="custom-block-title">Known limitation</p><p>MCP clients that send a resource indicator when signing in (Claude.ai, Claude Desktop and <code>mcp-remote</code>) currently receive tokens without the <code>delegate_exchange</code> scope, so the exchange is refused. Clients that sign in without a resource indicator are not affected. This needs a change in AireIdentity and will be lifted in a future release.</p></div><h2 id="custom-permission-source" tabindex="-1">Custom permission source <a class="header-anchor" href="#custom-permission-source" aria-label="Permalink to &quot;Custom permission source&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Documentation in progress</p><p>This section is a placeholder. Documentation for gating MCP tools with permissions held outside AireIdentity, using an AireGlu endpoint as a custom permission source, is coming soon.</p></div><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Gate tools by the action they perform.</strong> Use permissions that describe what the tool does (<code>read:patient</code>, <code>edit:appointment</code>), granted through AireIdentity roles.</li><li><strong>Use clear names and descriptions.</strong> Users only see their permitted tools, so each one should make sense on its own.</li><li><strong>Keep data rules downstream.</strong> Permission gating controls whether a tool is available, not which records it returns. Use Delegate Exchange so the downstream API can enforce per-user data access.</li><li><strong>Test with more than one user.</strong> Connect as a user with the permission and one without, and check the tool list differs as expected. Clear the client&#39;s cached sign-in (for <code>mcp-remote</code>, delete <code>~/.mcp-auth</code>) to switch users.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table><thead><tr><th>Issue</th><th>Things to check</th></tr></thead><tbody><tr><td>Client connects but every call fails</td><td>The user is missing <code>run:Mcp</code> on <code>AireGluMcp</code>.</td></tr><tr><td>A tool is missing for a user who should have it</td><td>Check the user holds <strong>every</strong> permission in <strong>every</strong> Target Scope on the target endpoint. Check the endpoint&#39;s <strong>Authority</strong> is AireIdentity and <strong>Audiences</strong> includes <code>AireGluMcp</code>.</td></tr><tr><td>A tool is missing for everyone</td><td>Check the gated endpoint authenticates successfully without gating (untick it temporarily), and that AireGlu can reach AireIdentity.</td></tr><tr><td>Tool shows but returns <em>Permission denied</em></td><td>The user&#39;s access changed after the list was fetched. Refresh the client&#39;s tool list.</td></tr><tr><td>Tool fails with a Delegate Exchange error</td><td>See <a href="/docs/connections/delegate-exchange.html#troubleshooting">Delegate Exchange troubleshooting</a> and the known limitation above.</td></tr></tbody></table>',37),d=[r];function c(l,h,u,p,g,m){return s(),t("div",null,d)}const b=e(i,[["render",c]]);export{w as __pageData,b as default};
